package com.clavis.reader;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.util.*;
/** Dedicated narration checks use an isolated private session, never user books. */
final class ListenChecks {
 static int checks;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static String run(Instrumentation test)throws Exception{Context c=test.getTargetContext();if(!NeuralModel.installed(c))NeuralModel.install(c,value->android.util.Log.i("ListenChecks",value));String sample="First sentence. Café and médecine stay intact.\n\n"+"This is another passage with punctuation and emoji 📖. ".repeat(60);StringBuilder rebuilt=new StringBuilder();for(int at=0;at<sample.length();){int end=NarrationText.end(sample,at);check(end>at&&end-at<=900,"Speech chunk bounded and progressing");check(end==sample.length()||!Character.isLowSurrogate(sample.charAt(end)),"Never split a surrogate pair");rebuilt.append(sample,at,end);at=end;}check(rebuilt.toString().equals(sample),"Every narration character preserved");check(NarrationText.clean("hy-\nphen\n\nnext").equals("hyphen\n\nnext"),"Clean wrapped hyphenation but preserve paragraphs");
 File file=ListenSession.file(c,"listen-check:"+System.nanoTime());ListenSession original=new ListenSession("fixture","Narration verification",sample);original.starts.add(0);original.labels.add("Page 7");original.save(file);ListenSession restored=ListenSession.read(file);check(restored.text.equals(sample)&&restored.label().equals("Page 7"),"Reading session round trip");android.content.SharedPreferences prefs=c.getSharedPreferences("listen",0);String last=prefs.getString("last",null);float speed=ListenService.defaultSpeed(c);int speaker=ListenService.defaultSpeaker(c);Activity activity=null;
 try{test.runOnMainSync(()->c.startActivity(new Intent(c,ListenActivity.class).putExtra("file",file.getAbsolutePath()).putExtra("autoplay",false).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));long deadline=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<deadline&&(ListenService.live==null||!ListenService.live.ready||ListenService.live.story==null))SystemClock.sleep(100);ListenService service=ListenService.live;check(service!=null&&service.ready,"Local TTS engine initialized");check(service.story!=null&&service.story.title.equals("Narration verification"),"Private session loads into shared player");final boolean[] offline={false};test.runOnMainSync(()->{offline[0]=NeuralModel.installed(c);check(offline[0],"Pinned offline neural model installed");service.seek(120);check(service.story.position>0,"Seek advances reading");service.setSpeed(1.25f);check(service.speed==1.25f,"Speed changes");service.skip(1);check(service.story.position>120,"Next passage advances");service.pause();check(!service.playing,"Pause stops speech");int forwardAt=NarrationText.skipWords(service.story.text,service.story.position,30);service.skip(1);check(service.story.position==NarrationText.wordStart(service.story.text,forwardAt),"Forward control seeks exactly thirty words");int backAt=NarrationText.skipWords(service.story.text,service.story.position,-30);service.skip(-1);check(service.story.position==NarrationText.wordStart(service.story.text,backAt),"Back control seeks exactly thirty words");check(!service.playing,"Word seeking preserves pause");service.setVoice(1);check(service.speaker==1&&prefs.getInt("speaker",0)==1,"Original voice selection persists");check(!service.playing,"Switching voice preserves pause");service.setVoice(0);check(service.speaker==0,"Male voice can be restored");if(offline[0]){service.play();check(service.neural!=null,"Dedicated Kitten neural voice is loaded");}});if(offline[0]){long speechDeadline=SystemClock.elapsedRealtime()+90000;while(service.speechStarts==0&&SystemClock.elapsedRealtime()<speechDeadline)SystemClock.sleep(100);test.runOnMainSync(()->{check(service.speechStarts>0,"Offline engine started audio synthesis");check(service.current!=null&&service.track!=null,"Neural PCM buffer is playing");check(Math.abs(service.track.getPlaybackParams().getSpeed()-1f)<.001f,"Narration speed is synthesized, not stretched");check(!service.status.contains("could not speak")&&!service.status.contains("failed"),"Offline synthesis reports no engine error");service.pause();});}test.runOnMainSync(()->{service.timer(5);check(service.sleepAt>SystemClock.elapsedRealtime(),"Sleep timer armed");service.timer(0);check(service.sleepAt==0,"Sleep timer disabled");service.stop();});SystemClock.sleep(500);for(int selected:new int[]{0,1}){prefs.edit().putInt("speaker",selected).putFloat("speed",.8f).commit();test.runOnMainSync(()->c.startForegroundService(new Intent(c,ListenService.class).putExtra("file",file.getAbsolutePath()).putExtra("autoplay",false)));long reopened=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<reopened&&(ListenService.live==null||!ListenService.live.ready||ListenService.live.story==null))SystemClock.sleep(100);ListenService resumed=ListenService.live;check(resumed!=null&&resumed.ready&&resumed.story!=null,"Listening reopens after close");check(resumed.speaker==selected,"Chosen voice survives closing and reopening");check(Math.abs(resumed.speed-.8f)<.001f,"0.8 speed survives closing and reopening");test.runOnMainSync(resumed::stop);SystemClock.sleep(500);}return checks+" narration checks passed; offline voices available: "+offline[0]+"\n";
 }finally{Activity close=activity;if(close!=null)test.runOnMainSync(close::finish);test.runOnMainSync(()->{if(ListenService.live!=null)ListenService.live.stop();});SystemClock.sleep(400);android.content.SharedPreferences.Editor edit=prefs.edit().putInt("speaker",speaker).putFloat("speed",speed);if(last==null)edit.remove("last");else edit.putString("last",last);edit.commit();c.getSharedPreferences("listen_progress",0).edit().remove(file.getName()).commit();file.delete();}}
}
